function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1) return 'matrix needs at least one row.';
  const n = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (n < 1) return 'matrix needs at least one column.';
  if (matrix.length * n > 100000) return 'm * n must be at most 10^5.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (!row.every(v => v === 0 || v === 1)) return 'Every cell is 0 or 1.';
  }
  return null;
}

