function largestSubmatrix(matrix) {
  // Try every band of rows; the columns that are all 1 inside the band can be moved next to each other.
  const m = matrix.length, n = matrix[0].length;
  let answer = 0;
  for (let top = 0; top < m; top++)
    for (let bottom = top; bottom < m; bottom++) {
      let full = 0;
      for (let c = 0; c < n; c++) {
        let allOnes = true;
        for (let r = top; r <= bottom; r++) if (matrix[r][c] !== 1) allOnes = false;
        if (allOnes) full++;
      }
      answer = Math.max(answer, full * (bottom - top + 1));
    }
  return answer;
}

