function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n, density;
  if (size === 'large') {
    m = pick(60, 100);
    n = pick(60, 100);
    density = 0.75 + rand() * 0.2;
  } else {
    m = pick(1, 6);
    n = pick(1, 6);
    density = [0, 0.3, 0.6, 0.8, 1][pick(0, 4)];
  }
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)))];
}
